        for (let i = 0; i < 10; i++) { ctx.fillStyle = "rgba(180,220,120,0.05)"; ctx.beginPath(); ctx.arc((i * 53) % W, (i * 31) % 90, 10 + (i % 3) * 6, 0, Math.PI * 2); ctx.fill(); } // dappled light
